import { t, L, esc } from '../core/i18n.js';
import { select, safeReturn } from '../core/store.js';
import { button, formField, pageHeader, notice, stepper, badge, showToast } from '../core/ui.js';
const label=k=>t('p2.'+k);
const steps=['identity','qualifications','credentials','review'];
const ret=ctx=>ctx.query.get('return')??'';
const authLink=(path,ctx)=>'#/auth/'+path+(ret(ctx)?'?return='+encodeURIComponent(ret(ctx)):'');
const submit=key=>`<button type="submit" class="btn btn-primary">${esc(label(key))}</button>`;
function field(form,name,extra={}) {return formField({id:form+'-'+name,name,label:label(name),value:select('form',{name:form}).values[name]??'',error:select('form',{name:form}).fieldErrors[name]?t(select('form',{name:form}).fieldErrors[name]):'',...extra});}
function shell(title,body) {return `<div class="auth-shell">${pageHeader({title,subtitle:label('authNote')})}<div class="panel stack">${body}</div></div>`;}
export const signIn={render(ctx){return shell(t('route./auth/sign-in'),`<form class="stack" data-action="auth.signIn" novalidate>${field('sign-in','persona',{type:'radio',value:select('form',{name:'sign-in'}).values.persona||'student',options:['student','guardian'].map(value=>({value,label:t('role.'+value)}))})}${field('sign-in','email',{type:'email',required:true})}${field('sign-in','password',{type:'password',required:true,hint:label('passwordHint')})}${submit('signIn')}</form><div class="flex-row">${['student','guardian'].map(r=>button({label:t('route./auth/register/'+r),href:authLink('register/'+r,ctx),variant:'secondary'})).join('')}${button({label:t('route./auth/reset-password'),href:authLink('reset-password',ctx),variant:'ghost'})}</div>`);}};
export const resetPassword={render(ctx){const f=select('form',{name:'reset-password'});return shell(t('route./auth/reset-password'),f.done?notice({message:label('resetDone'),tone:'success'})+button({label:label('signIn'),href:authLink('sign-in',ctx)}):`<form class="stack" data-action="auth.reset" novalidate>${field('reset-password','email',{type:'email',required:true})}${submit('send')}</form>`);}};
export const registration={render(ctx){const role=ctx.path.endsWith('/guardian')?'guardian':'student',name='register-'+role,f=select('form',{name});return shell(t('route./auth/register/'+role),f.done?notice({message:label('registerDone'),tone:'success'})+button({label:label('continue'),action:'auth.enter',data:{role}})+(role==='guardian'?button({label:label('linkChild'),action:'auth.linkChild',variant:'secondary'}):''):`<form class="stack" data-action="auth.register" data-role="${role}" novalidate>${field(name,'name',{required:true})}${role==='student'?field(name,'email',{type:'email',required:true})+field(name,'grade',{type:'select',required:true,options:[{value:'',label:label('choose')},...select('grades').map(g=>({value:g.id,label:L(g.name)}))]}):field(name,'contact',{required:true})}${field(name,'consent',{type:'checkbox',required:true,value:f.values.consent==='on',label:label('consent')})}${submit('register')}</form>`);}};
export const teacherApplication={render(ctx){const a=select('application.current'),step=steps.includes(ctx.query.get('step'))?ctx.query.get('step'):'identity',form=select('form',{name:'application'}),d={...a.data,...form.values};
 const control=(name,extra={})=>formField({id:'application-'+name,name,label:label(name),value:d[name]??'',error:form.fieldErrors[name]?t(form.fieldErrors[name]):'',...extra});
 const status=badge(a.application.state,{domain:'teacher_application'})+notice({message:L(a.application.feedback)||label('applicationPending')});
 if(!a.editable)return shell(t('route./auth/teacher-application'),status+notice({message:label(a.visitorOnly?'visitorApplication':'applicationLocked')}));
 let body='';
 if(step==='identity')body=['name','email','phone','bio'].map(name=>control(name,{type:name==='email'?'email':name==='bio'?'textarea':'text',required:name!=='phone'})).join('');
 if(step==='qualifications')body=notice({message:label('pairHint')})+(form.fieldErrors.pairs?notice({message:t(form.fieldErrors.pairs),tone:'error'}):'')+select('gradeSubjects.byGrade').map(g=>`<fieldset class="panel"><legend>${esc(L(g.name))}</legend>${g.pairs.map(p=>formField({id:'pair-'+p.id,name:'pairs',type:'checkbox',label:L(p.display_name),value:(d.pairs??[]).includes(p.id)}).replace('name="pairs"','name="pairs" value="'+esc(p.id)+'"')).join('')}</fieldset>`).join('');
 if(step==='credentials')body=notice({message:label('fileHint')})+[0,1].map(i=>`<fieldset class="stack"><legend>${esc(label('credential'))} ${i+1}</legend>${control('label'+i,{value:form.values['label'+i]??d.credentials[i]?.label??'',required:i===0})}${control('file'+i,{value:form.values['file'+i]??d.credentials[i]?.filename??'',hint:label('filenameHint'),required:i===0})}</fieldset>`).join('');
 if(step==='review')body=`<dl class="stack"><div><dt>${esc(label('name'))}</dt><dd>${esc(d.name)}</dd></div><div><dt>${esc(label('email'))}</dt><dd>${esc(d.email)}</dd></div><div><dt>${esc(label('bio'))}</dt><dd>${esc(d.bio)}</dd></div></dl><ul>${select('gradeSubjects.byGrade').flatMap(g=>g.pairs.filter(p=>d.pairs.includes(p.id)).map(p=>`<li>${esc(L(g.name))} · ${esc(L(p.display_name))}</li>`)).join('')}</ul><ul>${d.credentials.map(c=>`<li>${esc(c.label)} · <bdi>${esc(c.filename)}</bdi></li>`).join('')}</ul>${control('consent',{type:'checkbox',value:false,required:true})}`;
 return shell(t('route./auth/teacher-application'),status+stepper(steps.map(id=>({id,label:label(id)})),step,{label:label('application')})+`<nav class="flex-row">${steps.map(id=>button({label:label(id),href:'#/auth/teacher-application?step='+id,variant:'ghost'})).join('')}</nav><form class="stack" data-action="auth.application" data-step="${step}" novalidate>${body}${submit(step==='review'?'submitApplication':'next')}</form>`);
}};
function saveError(ctx,form,values,result) {ctx.dispatch('form.save',{form,values,fieldErrors:result.fieldErrors});if(result.errorKey)showToast(t(result.errorKey),{tone:'error'});}
function enter(ctx,role){if(!['student','guardian'].includes(role))return;ctx.dispatch('preferences.set',{role});ctx.navigate(safeReturn(ret(ctx),role)??'#/'+role);}
export function registerActions(register){register('auth',{
 signIn:(event,el,ctx)=>{if(event.type!=='submit')return;const values=Object.fromEntries(new FormData(el)),r=ctx.dispatch('auth.signIn',{...values,returnTo:ret(ctx)});if(!r.ok)return saveError(ctx,'sign-in',values,r);enter(ctx,r.data.role);},
 reset:(event,el,ctx)=>{if(event.type!=='submit')return;const values=Object.fromEntries(new FormData(el)),r=ctx.dispatch('auth.resetPassword',values);if(!r.ok)saveError(ctx,'reset-password',values,r);},
 register:(event,el,ctx)=>{if(event.type!=='submit')return;const role=el.dataset.role;if(!['student','guardian'].includes(role))return;const values=Object.fromEntries(new FormData(el)),r=ctx.dispatch(role==='student'?'auth.registerStudent':'auth.registerGuardian',values);if(!r.ok)saveError(ctx,'register-'+role,values,r);},
 enter:(_e,el,ctx)=>enter(ctx,el.dataset.role),
 linkChild:(_e,_el,ctx)=>{ctx.dispatch('preferences.set',{role:'guardian'});ctx.navigate('#/guardian/children/link');},
 application:(event,el,ctx)=>{if(event.type!=='submit')return;const step=el.dataset.step,fd=new FormData(el),values=Object.fromEntries(fd);if(step==='qualifications')values.pairs=fd.getAll('pairs');if(step==='credentials')values.credentials=[0,1].map(i=>({label:values['label'+i],filename:values['file'+i]}));const r=step==='review'?ctx.dispatch('application.submit',{consent:values.consent}):ctx.dispatch('application.saveStep',{step,values});if(!r.ok){saveError(ctx,'application',values,r);if(r.data?.step)ctx.navigate('#/auth/teacher-application?step='+r.data.step);return;}if(step==='review'){showToast(label('applicationDone'),{tone:'success'});ctx.navigate('#/auth/teacher-application?step=review');}else ctx.navigate('#/auth/teacher-application?step='+steps[steps.indexOf(step)+1]);}
});}
